"""Versioned read-only contracts. Events are generated by source systems, never guessed."""
from dataclasses import dataclass
import math
from typing import Any

CONTRACT_VERSION = 1

@dataclass(frozen=True)
class TradeEvent:
    run_id: str
    strategy_id: str
    symbol: str
    trade_id: str
    entry_ms: int
    exit_ms: int | None
    entry_price: float
    exit_price: float | None
    side: str
    quantity: float
    pnl: float | None

    @classmethod
    def parse(cls, raw: dict[str, Any]):
        e = cls(**raw)
        for field in ('entry_ms', 'exit_ms'):
            value = getattr(e, field)
            if value is None and field == 'exit_ms':
                continue
            if type(value) is not int or not 0 <= value < 2**63:
                raise ValueError('invalid trade timestamp')
        for field in ('entry_price', 'quantity', 'exit_price', 'pnl'):
            value = getattr(e, field)
            if value is None and field in ('exit_price', 'pnl'):
                continue
            try:
                finite = type(value) in (int, float) and math.isfinite(value)
            except OverflowError:
                finite = False
            if not finite:
                raise ValueError('invalid trade number')
        if e.side not in ('long','short') or e.entry_ms < 0 or e.entry_price <= 0 or e.quantity <= 0:
            raise ValueError('invalid trade event')
        if e.exit_ms is not None and e.exit_ms < e.entry_ms:
            raise ValueError('exit before entry')
        if (e.exit_ms is None) != (e.exit_price is None):
            raise ValueError('partial exit')
        if e.exit_price is not None and e.exit_price <= 0:
            raise ValueError('invalid exit price')
        return e


def align_trades(trades, start_ms, end_ms):
    """Clip display to viewport; preserve original entry and exit timestamps."""
    return [t for t in trades if t.entry_ms <= end_ms and (t.exit_ms is None or t.exit_ms >= start_ms)]


def aggregate_footprint(rows):
    """One POC per minute, tie-break to lowest price for deterministic display."""
    minutes = {}
    for r in rows:
        t, price, volume = int(r['t']), float(r['price']), float(r['volume'])
        if volume < 0: raise ValueError('negative volume')
        bucket = minutes.setdefault(t, {'t':t, 'levels':[], 'poc':None, 'poc_volume':-1.0})
        bucket['levels'].append(r)
        if volume > bucket['poc_volume'] or (volume == bucket['poc_volume'] and (bucket['poc'] is None or price < bucket['poc'])):
            bucket['poc'], bucket['poc_volume'] = price, volume
    return [minutes[t] for t in sorted(minutes)]


def poc_close_events(minutes, candles):
    """Diagnostic POC-close observations, NOT trading signals or backtest fills."""
    closes = {int(c['t']): float(c['c']) for c in candles}
    return [{'t':m['t'],'poc':m['poc'],'close':closes[m['t']], 'relation':'above' if closes[m['t']] > m['poc'] else 'below' if closes[m['t']] < m['poc'] else 'at'} for m in minutes if m['t'] in closes]
